<?php require __DIR__.'/includes/bootstrap.php';$title='Cart';require __DIR__.'/includes/header.php';$items=cart();$tot=cart_totals();?><div class="max-w-6xl mx-auto px-3 sm:px-5 py-8" x-data="cartUI()"><div class="flex justify-between items-end mb-6"><div><div class="text-xs tracking-[.2em] text-slate-400 font-black">YOUR CART</div><h1 class="text-3xl font-black">Cart</h1></div><div class="text-sm text-slate-500"><span x-text="count()">$count</span> items</div></div><div class="grid lg:grid-cols-[1fr_360px] gap-6"><div class="space-y-3"><template x-for="i in items" :key="i.key"><div class="bg-white border border-slate-200 rounded-2xl p-4 flex gap-4"><img :src="i.image || ('https://placehold.co/300x300/f1f5f9/111827?text='+encodeURIComponent(i.name))" class="w-24 h-24 rounded-xl object-cover"><div class="flex-1"><div class="font-black" x-text="i.name"></div><div class="text-xs text-slate-400 mt-1" x-text="[i.size,i.color,i.custom_name?'Name: '+i.custom_name:'',i.custom_number?'No: '+i.custom_number:''].filter(Boolean).join(' · ')"></div><div class="font-black mt-2" x-text="money(i.price)"></div><div class="flex items-center gap-2 mt-3"><button @click="update(i.key,i.qty-1)" class="w-8 h-8 rounded-lg bg-slate-100">−</button><span class="w-6 text-center font-bold" x-text="i.qty"></span><button @click="update(i.key,i.qty+1)" class="w-8 h-8 rounded-lg bg-slate-100">+</button></div></div><button @click="remove(i.key)" class="w-9 h-9 grid place-items-center"><span class="iconify text-lg" data-icon="solar:trash-bin-trash-linear"></span></button></div></template><?php if(!$items):?><div class="bg-white border rounded-2xl text-center py-20"><div class="text-4xl">🛒</div><div class="font-black mt-3">Your cart is empty</div><a href="/" class="inline-block mt-4 px-5 py-3 rounded-xl bg-slate-950 text-white font-bold">Continue Shopping</a></div><?php endif;?></div><div class="bg-white border border-slate-200 rounded-2xl p-5 h-fit sticky top-28"><div class="font-black text-lg">Order Summary</div><div class="space-y-3 mt-5 text-sm"><div class="flex justify-between"><span>Subtotal</span><b x-text="money(totals.subtotal)"></b></div><div class="flex justify-between"><span>Delivery</span><b x-text="money(totals.shipping)"></b></div><div class="flex justify-between"><span>Discount</span><b x-text="'-'+money(totals.discount)"></b></div><div class="border-t pt-3 flex justify-between text-lg"><span class="font-black">Total</span><b x-text="money(totals.total)"></b></div></div><a href="/checkout.php" class="mt-5 block text-center rounded-xl bg-slate-950 text-white py-3 font-black">Proceed to Checkout</a></div></div></div><script>function cartUI(){return{items:<?=json_encode(array_values($items),JSON_UNESCAPED_UNICODE)?>,totals:<?=json_encode($tot,JSON_UNESCAPED_UNICODE)?>,count(){return this.items.reduce((a,x)=>a+Number(x.qty),0)},money(n){return '৳'+Number(n||0).toLocaleString()},async req(body){const d=await api('/api/cart.php',body);if(d.ok){this.items=d.items||this.items;this.totals=d.totals;setCartCount(d.count)}},update(k,q){this.req({action:'update',key:k,qty:q})},remove(k){this.req({action:'remove',key:k})}}}</script><?php require __DIR__.'/includes/footer.php';?>
